SELECT c.* FROM content c
JOIN audio a ON a.id = c.audio_id
WHERE c.audio_id = #{audioId}
  AND a.is_delete = 0 AND a.visibility = #{publicVisibility}
  AND a.processing_status = #{ready} AND a.review_status = #{approved}
  AND c.is_delete = 0 AND c.status = #{published} AND c.visibility = #{publicVisibility}



            AND (c.like_count, c.create_time, c.id) < (#{cursor.likeCount}, #{cursor.createTime}, #{cursor.contentId})


            AND (c.create_time, c.id) < (#{cursor.createTime}, #{cursor.contentId})



ORDER BY c.like_count DESC, c.create_time DESC, c.id DESC
LIMIT #{limit}




SELECT c.id AS contentId, a.id AS audioId, a.index_version AS audioVersion
FROM content c JOIN audio a ON a.id = c.audio_id
WHERE c.id > #{afterId} AND a.review_status = #{banned}
  AND c.is_delete = 0 AND c.status IN (#{review}, #{published})
ORDER BY c.id LIMIT #{limit}
